CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    CREATE TABLE "AuditLogs" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "SourceService" character varying(50) NOT NULL,
        "UserId" integer,
        "OwnerProfileId" integer,
        "Action" character varying(100) NOT NULL,
        "EntityName" character varying(100) NOT NULL,
        "EntityId" character varying(50),
        "OldValuesJson" text,
        "NewValuesJson" text,
        "Reason" character varying(1000),
        "IpAddress" character varying(45),
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_AuditLogs" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    CREATE TABLE "FeatureFlags" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Key" character varying(100) NOT NULL,
        "IsEnabled" boolean NOT NULL,
        "Description" character varying(500),
        "UpdatedByUserId" integer,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_FeatureFlags" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    CREATE TABLE "OutboxMessages" (
        "Id" uuid NOT NULL,
        "EventType" character varying(200) NOT NULL,
        "PayloadJson" text NOT NULL,
        "OccurredAtUtc" timestamp with time zone NOT NULL,
        "ProcessedAtUtc" timestamp with time zone,
        "AttemptCount" integer NOT NULL,
        "LastError" character varying(2000),
        CONSTRAINT "PK_OutboxMessages" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    CREATE TABLE "Sanctions" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "OwnerProfileId" integer NOT NULL,
        "ParkingLotId" integer,
        "Level" character varying(40) NOT NULL,
        "Reason" character varying(1000) NOT NULL,
        "EvidenceJson" text,
        "StartsAtUtc" timestamp with time zone NOT NULL,
        "EndsAtUtc" timestamp with time zone,
        "Status" character varying(40) NOT NULL,
        "PenaltyAmount" numeric(18,2),
        "IssuedByUserId" integer NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_Sanctions" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    CREATE TABLE "SystemConfigs" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Key" character varying(100) NOT NULL,
        "Value" character varying(1000) NOT NULL,
        "DataType" character varying(20) NOT NULL,
        "Description" character varying(500),
        "UpdatedByUserId" integer,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_SystemConfigs" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    CREATE TABLE "RiskFlags" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "SubjectType" character varying(40) NOT NULL,
        "SubjectId" integer NOT NULL,
        "RuleCode" character varying(60) NOT NULL,
        "Severity" character varying(40) NOT NULL,
        "Status" character varying(40) NOT NULL,
        "Description" character varying(1000) NOT NULL,
        "EvidenceJson" text,
        "DueAtUtc" timestamp with time zone NOT NULL,
        "AssignedToUserId" integer,
        "ResolvedAtUtc" timestamp with time zone,
        "ResolutionNote" character varying(1000),
        "SanctionId" integer,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_RiskFlags" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_RiskFlags_Sanctions_SanctionId" FOREIGN KEY ("SanctionId") REFERENCES "Sanctions" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

