    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    CREATE INDEX "IX_RiskFlags_SanctionId" ON "RiskFlags" ("SanctionId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    CREATE INDEX "IX_RiskFlags_Status_Severity_DueAtUtc" ON "RiskFlags" ("Status", "Severity", "DueAtUtc");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    CREATE INDEX "IX_RiskFlags_SubjectType_SubjectId" ON "RiskFlags" ("SubjectType", "SubjectId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    CREATE INDEX "IX_Sanctions_OwnerProfileId_Status" ON "Sanctions" ("OwnerProfileId", "Status");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    CREATE INDEX "IX_Sanctions_ParkingLotId" ON "Sanctions" ("ParkingLotId") WHERE [ParkingLotId] IS NOT NULL;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    CREATE UNIQUE INDEX "IX_SystemConfigs_Key" ON "SystemConfigs" ("Key");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    PERFORM setval(
        pg_get_serial_sequence('"FeatureFlags"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "FeatureFlags") + 1,
            nextval(pg_get_serial_sequence('"FeatureFlags"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"SystemConfigs"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "SystemConfigs") + 1,
            nextval(pg_get_serial_sequence('"SystemConfigs"', 'Id'))),
        false);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092506_InitialCreate') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261003092506_InitialCreate', '10.0.12');
    END IF;
END $EF$;
COMMIT;

